APX.bo = {"country":{"name":"Bolivia","tagline":"Some of the world's highest vineyards, where wine and singani grow above 1,600 m on the edge of the tropics.","classification":"Bolivia's only protected wine-sector name is the denomination of origin *Singani*, recognised by Law 1334 of 4 May 1992 and reserved for grape brandy distilled from Muscat of Alexandria wines produced, distilled and bottled in defined zones: the central valley and provinces of Tarija (Cercado, Avilés, Méndez, Arce), the Nor and Sud Cinti valleys of Chuquisaca, Luribay, Sapahaqui and the Loayza and Murillo provinces of La Paz, and valleys of Potosí department such as Cotagaita and Turuchipa. 'Gran singani' must come from grapes grown above 1,600 m. Wines carry place names (Tarija, Valle de Cinti) without a formal appellation system."},"regions":[{"name":"Tarija","slug":"tarija","tagline":"Bolivia's high-altitude wine heartland.","ids":["bo-cotagaita-and-vitichi","bo-valle-central-de-tarija"]},{"name":"Valle de Cinti","slug":"valle-de-cinti","tagline":"Colonial vines climbing molle trees.","ids":["bo-valle-de-cinti"]},{"name":"Samaipata","slug":"samaipata","tagline":"Foothill vineyards near a pre-Inca fortress.","ids":["bo-samaipata"]}],"items":{"bo-cotagaita-and-vitichi":{"name":"Cotagaita and Vitichi","cat":"Region","subcat":"Wine area","region":"Tarija","styles":["sweet","red"],"summary":"Neighbouring valleys in Potosí department, with about 250 ha of vines (2008), roughly a tenth of Bolivia's vineyard, mostly traditional grapes for singani and local wine.","rslug":"tarija"},"bo-samaipata":{"name":"Samaipata","cat":"Region","subcat":"Wine area","region":"Samaipata","styles":["red","white"],"summary":"Samaipata, in the Andean foothills of Santa Cruz department at about 1,700 m, is a young wine area near a famous pre-Inca site. Small wineries such as Uvairenda (Vinos 1750) and Landsuá make fresh reds and whites in a more humid climate.","producers":["Uvairenda (1750)","Bodegas Landsuá"],"rslug":"samaipata"},"bo-valle-central-de-tarija":{"name":"Valle Central de Tarija","cat":"Region","subcat":"Wine area","region":"Tarija","styles":["red","white","sweet"],"grapes":"Tannat, Malbec, Cabernet Sauvignon, Syrah, Merlot, Moscatel de Alejandría, Torrontés","summary":"The central valley of Tarija, at about 1,600 to 2,150 m, holds most of Bolivia's vineyards and wineries around the city of Tarija, Concepción (Uriondo), Santa Ana and La Pintada. A mild, semi-arid climate with summer rain, winds and cool nights favours Tannat, Malbec, Cabernet Sauvignon, Syrah and Muscat for singani. Kohlberg, Aranjuez, Campos de Solana, Casa Vieja, La Concepción and Magnus are based here.","producers":["Bodegas Kohlberg","Aranjuez","Campos de Solana","La Concepción","La Casa Vieja","Bodega Magnus"],"nerd_note":"Tarija's Concepción valley in Uriondo is the hub of Bolivia's wine route, with adobe wineries and Casa Vieja's traditional cellar.","rslug":"tarija"},"bo-valle-de-cinti":{"name":"Valle de Cinti","cat":"Region","subcat":"Wine area","region":"Valle de Cinti","styles":["red","white","sweet"],"grapes":"Negra Criolla, Moscatel de Alejandría, Vischoqueña","summary":"The Cinti valley in Chuquisaca, around Camargo and Villa Abecia at about 2,400 m, is the spiritual home of Bolivian traditional winemaking. Its colonial vineyards, some 100 to 250 years old, climb native molle and chañar trees in a narrow red-rock canyon, a training system found almost nowhere else. Old Negra Criolla, Moscatel and Vischoqueña vines make singani and small-batch wines that have attracted a new generation of producers since 2000.","nerd_note":"About 300 ha of vineyard in Cinti include around 30 vineyards with vines trained up living trees.","rslug":"valle-de-cinti"}}};
